mapper.select:
SELECT *
FROM TRADE
WHERE TRADE_ID = #{tradeId}
  AND MEMBER_ID = #{memberId}

mapper.delete:
DELETE FROM TRADE
WHERE TRADE_ID = #{tradeId}
  AND MEMBER_ID = #{memberId}

mapper.select:
SELECT COUNT(*)
FROM TRADE
WHERE MEMBER_ID = #{memberId}

SELECT NVL(
    SUM((SELL_PRICE - BUY_PRICE) * QUANTITY),
    0
)
FROM TRADE
WHERE MEMBER_ID = #{memberId}

SELECT NVL(
    AVG(
        (SELL_PRICE - BUY_PRICE)
        / BUY_PRICE * 100
    ),
    0
)
FROM TRADE
WHERE MEMBER_ID = #{memberId}
